cat > /app/submission/main.py <<'PYEOF'
#!/usr/bin/env python3
"""Offline finite-domain network rule mining service.

Reads one JSON request on stdin, writes one JSON response on stdout, exits 0.
Implements the contract described in the task statement using only the
Python standard library.
"""
import json
import re
import sys
from fractions import Fraction

MAX_INPUT_BYTES = 8388608
MAX_DEPTH = 64
MAX_TRACES = 128
MAX_ROWS = 16384
MAX_TRAIN_CTX = 4096
MAX_PROBE_CTX = 128
MAX_QUERY_CTX = 1024
MAX_TRAIN_SOURCES = 16

NUMERIC_TYPES = ("TIME", "SIZE", "COUNT")
ALL_TYPES = ("TIME", "SIZE", "COUNT", "ID", "FLAG")
CMP_OPS = {"eq": "==", "ne": "!=", "lt": "<", "le": "<=", "gt": ">", "ge": ">="}
EQ_OPS = ("eq", "ne")
AGG_OPS = ("sum", "mean", "min", "max")

RE_NAME = re.compile(r"[a-z][a-z0-9_]{0,31}\Z")
RE_IDVAL = re.compile(r"[A-Za-z0-9_.:\-]{1,32}\Z")
RE_TID = re.compile(r"[A-Za-z][A-Za-z0-9_\-]{0,31}\Z")

I32_LO = -(2 ** 31)
I32_HI = 2 ** 31 - 1


class ServiceError(Exception):
    def __init__(self, code):
        Exception.__init__(self, code)
        self.code = code


def die(code):
    raise ServiceError(code)


# --------------------------------------------------------------------------
# small type helpers (JSON booleans are never integers in this contract)
# --------------------------------------------------------------------------
def is_int(v):
    return type(v) is int


def is_bool(v):
    return type(v) is bool


def is_str(v):
    return type(v) is str


def is_i32(v):
    return type(v) is int and I32_LO <= v <= I32_HI


# --------------------------------------------------------------------------
# JSON front end
# --------------------------------------------------------------------------
def _bad_constant(_name):
    die("E_JSON")


def _parse_float(text):
    try:
        val = float(text)
    except ValueError:
        die("E_JSON")
    if val != val or val in (float("inf"), float("-inf")):
        die("E_JSON")
    return val


def _object_hook(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            die("E_JSON")
        out[key] = value
    return out


def check_depth(obj):
    """Container nesting depth; root container has depth 1."""
    if not isinstance(obj, (dict, list)):
        return
    stack = [(obj, 1)]
    while stack:
        node, depth = stack.pop()
        if depth > MAX_DEPTH:
            die("E_JSON")
        child_depth = depth + 1
        if isinstance(node, dict):
            for value in node.values():
                if isinstance(value, (dict, list)):
                    stack.append((value, child_depth))
        else:
            for value in node:
                if isinstance(value, (dict, list)):
                    stack.append((value, child_depth))


def parse_request(raw):
    if len(raw) > MAX_INPUT_BYTES:
        die("E_LIMIT")
    if raw.startswith(b"\xef\xbb\xbf"):
        die("E_JSON")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        die("E_JSON")
    try:
        obj = json.loads(text, object_pairs_hook=_object_hook,
                         parse_constant=_bad_constant, parse_float=_parse_float)
    except ServiceError:
        raise
    except RecursionError:
        die("E_JSON")
    except ValueError:
        die("E_JSON")
    check_depth(obj)
    return obj


# --------------------------------------------------------------------------
# request validation
# --------------------------------------------------------------------------
TOP_KEYS = frozenset(("version", "schema", "window", "atoms", "policy",
                      "train", "probes", "queries"))


def validate_schema(sch):
    if not isinstance(sch, list) or not (1 <= len(sch) <= 32):
        die("E_SCHEMA")
    fields = []
    names = set()
    for item in sch:
        if not isinstance(item, dict):
            die("E_SCHEMA")
        keys = set(item.keys())
        if "name" not in keys or "type" not in keys:
            die("E_SCHEMA")
        name = item["name"]
        ftype = item["type"]
        if not is_str(name) or RE_NAME.fullmatch(name) is None:
            die("E_SCHEMA")
        if name in names:
            die("E_SCHEMA")
        names.add(name)
        if not is_str(ftype) or ftype not in ALL_TYPES:
            die("E_SCHEMA")
        if ftype in NUMERIC_TYPES:
            if keys != {"name", "type", "min", "max"}:
                die("E_SCHEMA")
            lo = item["min"]
            hi = item["max"]
            if not is_i32(lo) or not is_i32(hi) or lo > hi:
                die("E_SCHEMA")
            fields.append({"name": name, "type": ftype, "min": lo, "max": hi,
                           "values": None})
        elif ftype == "ID":
            if keys != {"name", "type", "values"}:
                die("E_SCHEMA")
            vals = item["values"]
            if not isinstance(vals, list) or not (1 <= len(vals) <= 32):
                die("E_SCHEMA")
            vset = set()
            for v in vals:
                if not is_str(v) or RE_IDVAL.fullmatch(v) is None or v in vset:
                    die("E_SCHEMA")
                vset.add(v)
            fields.append({"name": name, "type": "ID", "min": None, "max": None,
                           "values": vset})
        else:  # FLAG
            if keys != {"name", "type"}:
                die("E_SCHEMA")
            fields.append({"name": name, "type": "FLAG", "min": None, "max": None,
                           "values": None})
    return fields


def validate_policy(pol):
    if not isinstance(pol, dict):
        die("E_SCHEMA")
    if set(pol.keys()) != {"max_width", "min_support", "min_witness"}:
        die("E_SCHEMA")
    width = pol["max_width"]
    supp = pol["min_support"]
    wit = pol["min_witness"]
    if not (is_int(width) and 1 <= width <= 4):
        die("E_SCHEMA")
    if not (is_int(supp) and 1 <= supp <= 4096):
        die("E_SCHEMA")
    if not (is_int(wit) and 1 <= wit <= 4096):
        die("E_SCHEMA")
    return width, supp, wit


def validate_term(node, K, fbn, quantified, counter):
    """Return (type, depth). Enforces grammar, ranges and node budget."""
    if not isinstance(node, dict):
        die("E_SCHEMA")
    keys = set(node.keys())
    if keys == {"field", "at"}:
        fname = node["field"]
        at = node["at"]
        fld = fbn.get(fname) if is_str(fname) else None
        if fld is None:
            die("E_SCHEMA")
        if is_int(at):
            if not (0 <= at < K):
                die("E_SCHEMA")
        elif is_str(at) and at == "$":
            if not quantified:
                die("E_SCHEMA")
        else:
            die("E_SCHEMA")
        counter[0] += 1
        if counter[0] > 64:
            die("E_SCHEMA")
        return fld["type"], 1
    if keys == {"const", "type"}:
        ctype = node["type"]
        cval = node["const"]
        if not is_str(ctype) or ctype not in ALL_TYPES:
            die("E_SCHEMA")
        if ctype in NUMERIC_TYPES:
            if not is_i32(cval):
                die("E_SCHEMA")
        elif ctype == "ID":
            if not is_str(cval) or RE_IDVAL.fullmatch(cval) is None:
                die("E_SCHEMA")
        else:
            if not is_bool(cval):
                die("E_SCHEMA")
        counter[0] += 1
        if counter[0] > 64:
            die("E_SCHEMA")
        return ctype, 1
    if keys == {"scale", "term"}:
        factor = node["scale"]
        if not (is_int(factor) and -1024 <= factor <= 1024):
            die("E_SCHEMA")
        ctype, cdepth = validate_term(node["term"], K, fbn, quantified, counter)
        if ctype not in NUMERIC_TYPES:
            die("E_SCHEMA")
        counter[0] += 1
        if counter[0] > 64:
            die("E_SCHEMA")
        return ctype, cdepth + 1
    if keys == {"add"}:
        parts = node["add"]
        if not isinstance(parts, list) or len(parts) != 2:
            die("E_SCHEMA")
        t1, d1 = validate_term(parts[0], K, fbn, quantified, counter)
        t2, d2 = validate_term(parts[1], K, fbn, quantified, counter)
        if t1 not in NUMERIC_TYPES or t1 != t2:
            die("E_SCHEMA")
        counter[0] += 1
        if counter[0] > 64:
            die("E_SCHEMA")
        return t1, (d1 if d1 > d2 else d2) + 1
    if keys == {"aggregate", "field", "from", "to"}:
        op = node["aggregate"]
        fname = node["field"]
        lo = node["from"]
        hi = node["to"]
        if not is_str(op) or op not in AGG_OPS:
            die("E_SCHEMA")
        fld = fbn.get(fname) if is_str(fname) else None
        if fld is None or fld["type"] not in NUMERIC_TYPES:
            die("E_SCHEMA")
        if not (is_int(lo) and is_int(hi)):
            die("E_SCHEMA")
        if not (0 <= lo <= hi < K):
            die("E_SCHEMA")
        counter[0] += 1
        if counter[0] > 64:
            die("E_SCHEMA")
        return fld["type"], 1
    die("E_SCHEMA")


def validate_cmp(node, K, fbn, quantified, counter):
    if not isinstance(node, dict):
        die("E_SCHEMA")
    if set(node.keys()) != {"cmp", "left", "right"}:
        die("E_SCHEMA")
    op = node["cmp"]
    if not is_str(op) or op not in CMP_OPS:
        die("E_SCHEMA")
    tleft, dleft = validate_term(node["left"], K, fbn, quantified, counter)
    tright, dright = validate_term(node["right"], K, fbn, quantified, counter)
    if dleft > 4 or dright > 4:
        die("E_SCHEMA")
    if tleft != tright:
        die("E_SCHEMA")
    if tleft not in NUMERIC_TYPES and op not in EQ_OPS:
        die("E_SCHEMA")
    return tleft


def validate_atom(atom, K, fbn):
    if not isinstance(atom, dict):
        die("E_SCHEMA")
    keys = set(atom.keys())
    if keys == {"cmp", "left", "right"}:
        validate_cmp(atom, K, fbn, False, [0])
    elif keys == {"quantifier", "from", "to", "predicate"}:
        quant = atom["quantifier"]
        if not is_str(quant) or quant not in ("any", "all"):
            die("E_SCHEMA")
        lo = atom["from"]
        hi = atom["to"]
        if not (is_int(lo) and is_int(hi)):
            die("E_SCHEMA")
        if not (0 <= lo <= hi < K):
            die("E_SCHEMA")
        validate_cmp(atom["predicate"], K, fbn, True, [0])
    else:
        die("E_SCHEMA")


def validate_row_values(vals, fields):
    if not isinstance(vals, list) or len(vals) != len(fields):
        die("E_SCHEMA")
    out = []
    for idx in range(len(fields)):
        fld = fields[idx]
        val = vals[idx]
        ftype = fld["type"]
        if ftype == "FLAG":
            if not is_bool(val):
                die("E_SCHEMA")
        elif ftype == "ID":
            if not is_str(val) or RE_IDVAL.fullmatch(val) is None:
                die("E_SCHEMA")
            if val not in fld["values"]:
                die("E_SCHEMA")
        else:
            if not is_int(val) or val < fld["min"] or val > fld["max"]:
                die("E_SCHEMA")
        out.append(val)
    return tuple(out)


def validate_traces(arr, fields, seen_ids, counters):
    if not isinstance(arr, list):
        die("E_SCHEMA")
    traces = []
    for tr in arr:
        if not isinstance(tr, dict):
            die("E_SCHEMA")
        if set(tr.keys()) != {"id", "source", "rows"}:
            die("E_SCHEMA")
        tid = tr["id"]
        src = tr["source"]
        rows = tr["rows"]
        if not is_str(tid) or RE_TID.fullmatch(tid) is None:
            die("E_SCHEMA")
        if not is_str(src) or RE_TID.fullmatch(src) is None:
            die("E_SCHEMA")
        if tid in seen_ids:
            die("E_SCHEMA")
        seen_ids.add(tid)
        if not isinstance(rows, list):
            die("E_SCHEMA")
        counters["traces"] += 1
        if counters["traces"] > MAX_TRACES:
            die("E_SCHEMA")
        parsed_rows = []
        seen_t = set()
        for row in rows:
            if not isinstance(row, dict):
                die("E_SCHEMA")
            if set(row.keys()) != {"t", "values"}:
                die("E_SCHEMA")
            tval = row["t"]
            if not is_i32(tval):
                die("E_SCHEMA")
            if tval in seen_t:
                die("E_SCHEMA")
            seen_t.add(tval)
            parsed_rows.append((tval, validate_row_values(row["values"], fields)))
            counters["rows"] += 1
            if counters["rows"] > MAX_ROWS:
                die("E_SCHEMA")
        parsed_rows.sort(key=lambda item: item[0])
        traces.append({"id": tid, "source": src, "rows": parsed_rows})
    return traces


def build_contexts(traces, K):
    contexts = []
    for tr in traces:
        rows = tr["rows"]
        n = len(rows)
        if n < K:
            continue
        vals = [r[1] for r in rows]
        times = [r[0] for r in rows]
        tid = tr["id"]
        src = tr["source"]
        for i in range(n - K + 1):
            contexts.append((tuple(vals[i:i + K]), tid, src, times[i + K - 1]))
    return contexts


# --------------------------------------------------------------------------
# atom compilation (exact arithmetic, no floating point)
# --------------------------------------------------------------------------
def gen_term(node, fidx, binding):
    keys = set(node.keys())
    if keys == {"field", "at"}:
        at = node["at"]
        if is_str(at):
            if binding is None:
                die("E_SCHEMA")
            off = binding
        else:
            off = at
        return "r[%d][%d]" % (off, fidx[node["field"]])
    if keys == {"const", "type"}:
        val = node["const"]
        if type(val) is bool:
            return "(True)" if val else "(False)"
        if is_int(val):
            return "(%d)" % val
        return repr(val)
    if keys == {"scale", "term"}:
        return "(%d*%s)" % (node["scale"], gen_term(node["term"], fidx, binding))
    if keys == {"add"}:
        parts = node["add"]
        return "(%s+%s)" % (gen_term(parts[0], fidx, binding),
                            gen_term(parts[1], fidx, binding))
    # aggregate
    op = node["aggregate"]
    fi = fidx[node["field"]]
    terms = ["r[%d][%d]" % (d, fi) for d in range(node["from"], node["to"] + 1)]
    if op == "sum":
        return "(" + "+".join(terms) + ")"
    if op == "min":
        return "min(%s)" % (",".join(terms),)
    if op == "max":
        return "max(%s)" % (",".join(terms),)
    return "_F((%s),%d)" % ("+".join(terms), len(terms))


def gen_cmp(node, fidx, binding):
    return "(%s%s%s)" % (gen_term(node["left"], fidx, binding),
                         CMP_OPS[node["cmp"]],
                         gen_term(node["right"], fidx, binding))


def compile_atoms(atoms, fidx):
    env = {"_F": Fraction, "min": min, "max": max, "sum": sum}
    fns = []
    for atom in atoms:
        if "quantifier" in atom:
            pred = atom["predicate"]
            bodies = [gen_cmp(pred, fidx, j)
                      for j in range(atom["from"], atom["to"] + 1)]
            joiner = " or " if atom["quantifier"] == "any" else " and "
            expr = "(" + joiner.join(bodies) + ")"
        else:
            expr = gen_cmp(atom, fidx, None)
        fns.append(eval("lambda r: " + expr, dict(env)))  # noqa: S307
    return fns


def eval_partition(contexts, fns):
    natoms = len(fns)
    bits = [0] * natoms
    for idx, ctx in enumerate(contexts):
        rowset = ctx[0]
        bit = 1 << idx
        for a in range(natoms):
            if fns[a](rowset):
                bits[a] |= bit
    return bits


# --------------------------------------------------------------------------
# mining
# --------------------------------------------------------------------------
class BitCounter(object):
    """Bit-sliced multiset counter: add bitsets, later read per-position counts."""

    __slots__ = ("bits",)

    def __init__(self):
        self.bits = []

    def add(self, value):
        bits = self.bits
        k = 0
        while value:
            if k == len(bits):
                bits.append(0)
            carry = bits[k] & value
            bits[k] ^= value
            value = carry
            k += 1

    def count_at(self, pos):
        total = 0
        weight = 1
        for b in self.bits:
            if (b >> pos) & 1:
                total += weight
            weight <<= 1
        return total


def mine(train_ctx, probe_ctx, query_ctx, train_bits, probe_bits, query_bits,
         natoms, width_limit, min_support, min_witness, ntrain, nprobe, nquery):
    classes = {}
    if natoms == 0 or ntrain is None:
        return classes
    full_tr = (1 << ntrain) - 1
    full_pr = (1 << nprobe) - 1
    full_q = (1 << nquery) - 1

    # per-source masks over training contexts
    src_index = {}
    for ctx in train_ctx:
        s = src_index.get(ctx[2])
        if s is None:
            s = len(src_index)
            src_index[ctx[2]] = s
    nsources = len(src_index)
    if nsources == 0 or nprobe == 0:
        return classes
    src_mask = [0] * nsources
    for idx, ctx in enumerate(train_ctx):
        src_mask[src_index[ctx[2]]] |= 1 << idx

    lit_tr = [None] * (2 * natoms)
    lit_pr = [None] * (2 * natoms)
    lit_q = [None] * (2 * natoms)
    for a in range(natoms):
        lit_tr[2 * a] = train_bits[a]
        lit_tr[2 * a + 1] = full_tr ^ train_bits[a]
        lit_pr[2 * a] = probe_bits[a]
        lit_pr[2 * a + 1] = full_pr ^ probe_bits[a]
        lit_q[2 * a] = query_bits[a]
        lit_q[2 * a + 1] = full_q ^ query_bits[a]

    thresh_pooled = min_witness * nsources

    def witness_ok(wset):
        if wset.bit_count() < thresh_pooled:
            return False
        for s in range(nsources):
            if (wset & src_mask[s]).bit_count() < min_witness:
                return False
        return True

    def supported(li):
        bits = lit_tr[li]
        for s in range(nsources):
            if (bits & src_mask[s]).bit_count() < min_support:
                return False
        return True

    supp_negs = []
    for a in range(natoms):
        choices = []
        if supported(2 * a):
            choices.append(False)
        if supported(2 * a + 1):
            choices.append(True)
        supp_negs.append(choices)

    # suffix union of training coverage of all supported literals from atom i on
    suffix = [0] * (natoms + 1)
    acc = 0
    for a in range(natoms - 1, -1, -1):
        for neg in supp_negs[a]:
            acc |= lit_tr[2 * a + (1 if neg else 0)]
        suffix[a] = acc

    clause = []  # list of (literal index, train bits)

    def leaf(orset_tr, orset_pr, orset_q):
        if orset_tr != full_tr:
            return
        if orset_pr == full_pr:
            return
        n = len(clause)
        for i in range(n):
            li, bits = clause[i]
            others = 0
            for j in range(n):
                if j != i:
                    others |= clause[j][1]
            if not witness_ok(bits & ~others):
                return
        entry = classes.get(orset_pr)
        if entry is None:
            classes[orset_pr] = [1, tuple(li for li, _ in clause), orset_q,
                                 full_q & orset_q | (full_q ^ full_q) if False else orset_q,
                                 full_q]
            # entry layout: [count, representative, or-set, and-set]
            entry = classes[orset_pr]
            entry[2] = orset_q
            entry[3] = full_q & orset_q
        else:
            entry[0] += 1
            entry[2] |= orset_q
            entry[3] &= orset_q

    def dfs(start, orset_tr, orset_pr, orset_q):
        if clause:
            leaf(orset_tr, orset_pr, orset_q)
        if len(clause) >= width_limit:
            return
        for a in range(start, natoms):
            choices = supp_negs[a]
            if not choices:
                continue
            if (orset_tr | suffix[a]) != full_tr:
                break
            for neg in choices:
                li = 2 * a + (1 if neg else 0)
                bits = lit_tr[li]
                fresh = bits & ~orset_tr
                if fresh == 0:
                    continue
                if not witness_ok(fresh):
                    continue
                clause.append((li, bits))
                dfs(a + 1, orset_tr | bits, orset_pr | lit_pr[li],
                    orset_q | lit_q[li])
                clause.pop()

    dfs(0, 0, 0, 0)
    return classes


def format_signature(sig, nprobe):
    width = (nprobe + 3) // 4
    return "%0*x" % (width, sig)


def handle(raw):
    req = parse_request(raw)
    if not isinstance(req, dict):
        die("E_SCHEMA")
    if set(req.keys()) != TOP_KEYS:
        die("E_SCHEMA")
    if not (is_int(req["version"]) and req["version"] == 1):
        die("E_SCHEMA")
    K = req["window"]
    if not (is_int(K) and 1 <= K <= 8):
        die("E_SCHEMA")
    fields = validate_schema(req["schema"])
    width_limit, min_support, min_witness = validate_policy(req["policy"])
    atoms = req["atoms"]
    if not isinstance(atoms, list) or not (0 <= len(atoms) <= 20):
        die("E_SCHEMA")
    fbn = {}
    for idx, fld in enumerate(fields):
        fbn[fld["name"]] = fld
        fld["index"] = idx
    for atom in atoms:
        validate_atom(atom, K, fbn)

    counters = {"traces": 0, "rows": 0}
    seen_ids = set()
    train_traces = validate_traces(req["train"], fields, seen_ids, counters)
    probe_traces = validate_traces(req["probes"], fields, seen_ids, counters)
    query_traces = validate_traces(req["queries"], fields, seen_ids, counters)

    train_sources = []
    train_src_seen = set()
    for tr in train_traces:
        if tr["source"] not in train_src_seen:
            train_src_seen.add(tr["source"])
            train_sources.append(tr["source"])
    if len(train_sources) > MAX_TRAIN_SOURCES:
        die("E_SCHEMA")

    train_ctx = build_contexts(train_traces, K)
    probe_ctx = build_contexts(probe_traces, K)
    query_ctx = build_contexts(query_traces, K)
    if len(train_ctx) > MAX_TRAIN_CTX:
        die("E_SCHEMA")
    if len(probe_ctx) > MAX_PROBE_CTX:
        die("E_SCHEMA")
    if len(query_ctx) > MAX_QUERY_CTX:
        die("E_SCHEMA")

    natoms = len(atoms)
    fidx = {}
    for fld in fields:
        fidx[fld["name"]] = fld["index"]
    fns = compile_atoms(atoms, fidx)

    ntrain = len(train_ctx)
    nprobe = len(probe_ctx)
    nquery = len(query_ctx)

    train_bits = eval_partition(train_ctx, fns) if natoms else []
    probe_bits = eval_partition(probe_ctx, fns) if natoms else []
    query_bits = eval_partition(query_ctx, fns) if natoms else []

    classes = {}
    if natoms and len(train_sources) >= 1 and nprobe >= 1:
        classes = mine(train_ctx, probe_ctx, query_ctx, train_bits, probe_bits,
                       query_bits, natoms, width_limit, min_support, min_witness,
                       ntrain, nprobe, nquery)

    classes_out = []
    for sig, entry in classes.items():
        count, rep, _orset, _andset = entry
        classes_out.append({
            "signature": format_signature(sig, nprobe),
            "members": count,
            "representative": {"or": [{"atom": li >> 1, "negated": (li & 1) == 1}
                                      for li in rep]},
        })

    counter_must = BitCounter()
    counter_may = BitCounter()
    full_q = (1 << nquery) - 1
    for entry in classes.values():
        counter_must.add(full_q ^ entry[2])
        counter_may.add(full_q ^ entry[3])

    queries_out = []
    for idx, ctx in enumerate(query_ctx):
        must = counter_must.count_at(idx)
        may = counter_may.count_at(idx)
        if must > 0:
            status = "violating"
        elif may > 0:
            status = "ambiguous"
        else:
            status = "consistent"
        queries_out.append({"trace": ctx[1], "end": ctx[3], "must": must,
                            "may": may, "status": status})

    return {"version": 1, "classes": classes_out, "queries": queries_out}


def main():
    raw = sys.stdin.buffer.read(MAX_INPUT_BYTES + 1)
    if len(raw) <= MAX_INPUT_BYTES:
        # cheap path: whole request already in memory
        pass
    try:
        resp = handle(raw)
    except ServiceError as exc:
        resp = {"error": exc.code}
    except Exception:  # pragma: no cover - defensive
        import traceback
        traceback.print_exc(file=sys.stderr)
        resp = {"error": "E_SCHEMA"}
    out = json.dumps(resp)
    sys.stdout.write(out)
    sys.stdout.write("\n")
    sys.stdout.flush()


if __name__ == "__main__":
    main()
