"""Independent slow reference implementation of the mining contract.

Assumes the request is valid (no validation). Uses straightforward list based
truth tables and Fraction arithmetic everywhere.
"""
import itertools
import json
import sys
from fractions import Fraction

NUM = ("TIME", "SIZE", "COUNT")


def term_type(t, fbn, K, quant, depth=0):
    keys = set(t.keys())
    if keys == {"field", "at"}:
        at = t["at"]
        assert isinstance(at, int) or (at == "$" and quant)
        if isinstance(at, int):
            assert 0 <= at < K
        return fbn[t["field"]]["type"], 1
    if keys == {"const", "type"}:
        return t["type"], 1
    if keys == {"scale", "term"}:
        ty, d = term_type(t["term"], fbn, K, quant, depth + 1)
        assert ty in NUM
        return ty, d + 1
    if keys == {"add"}:
        (t1, d1), (t2, d2) = [term_type(x, fbn, K, quant, depth + 1) for x in t["add"]]
        assert t1 == t2 and t1 in NUM
        return t1, max(d1, d2) + 1
    if keys == {"aggregate", "field", "from", "to"}:
        assert t["aggregate"] in ("sum", "mean", "min", "max")
        ty = fbn[t["field"]]["type"]
        assert ty in NUM
        assert 0 <= t["from"] <= t["to"] < K
        return ty, 1
    raise AssertionError("bad term %r" % (t,))


def eval_term(t, rows, binding=None):
    keys = set(t.keys())
    if keys == {"field", "at"}:
        at = t["at"]
        off = binding if at == "$" else at
        v = rows[off][t["field"]]
        return v
    if keys == {"const", "type"}:
        v = t["const"]
        if t["type"] in NUM:
            return Fraction(v)
        return v
    if keys == {"scale", "term"}:
        return Fraction(t["scale"]) * eval_term(t["term"], rows, binding)
    if keys == {"add"}:
        a, b = t["add"]
        return eval_term(a, rows, binding) + eval_term(b, rows, binding)
    if keys == {"aggregate", "field", "from", "to"}:
        vals = [Fraction(rows[d][t["field"]]) for d in range(t["from"], t["to"] + 1)]
        op = t["aggregate"]
        if op == "sum":
            return sum(vals, Fraction(0))
        if op == "min":
            return min(vals)
        if op == "max":
            return max(vals)
        return Fraction(sum(vals, Fraction(0)), len(vals))
    raise AssertionError("bad term")


def eval_cmp(c, rows, binding=None):
    op = c["cmp"]
    lv = eval_term(c["left"], rows, binding)
    rv = eval_term(c["right"], rows, binding)
    return {"eq": lv == rv, "ne": lv != rv, "lt": lv < rv, "le": lv <= rv,
            "gt": lv > rv, "ge": lv >= rv}[op]


def eval_atom(atom, rows):
    if "quantifier" in atom:
        vals = [eval_cmp(atom["predicate"], rows, j)
                for j in range(atom["from"], atom["to"] + 1)]
        return any(vals) if atom["quantifier"] == "any" else all(vals)
    return eval_cmp(atom, rows)


def contexts(traces, K):
    out = []
    for tr in traces:
        rows = sorted(tr["rows"], key=lambda r: r["t"])
        vals = [r["values"] for r in rows]
        n = len(vals)
        for i in range(n - K + 1):
            out.append((tr["id"], tr["source"], rows[i + K - 1]["t"], vals[i:i + K]))
    return out


def rows_to_dicts(ctx_rows, fields):
    out = []
    for row in ctx_rows:
        d = {}
        for i, f in enumerate(fields):
            v = row[i]
            d[f["name"]] = Fraction(v) if f["type"] in NUM else v
        out.append(d)
    return out


def solve(req):
    K = req["window"]
    fields = req["schema"]
    fbn = {f["name"]: f for f in fields}
    atoms = req["atoms"]
    pol = req["policy"]
    B, S, W = pol["max_width"], pol["min_support"], pol["min_witness"]

    def part(name):
        cs = contexts(req[name], K)
        return [(tid, src, endt, rows_to_dicts(rows, fields)) for tid, src, endt, rows in cs]

    train = part("train")
    probes = part("probes")
    queries = part("queries")

    sources = []
    for tr in req["train"]:
        if tr["source"] not in sources:
            sources.append(tr["source"])

    # atom truth tables
    tr_tab = [[eval_atom(a, rows) for a in atoms] for (_t, _s, _e, rows) in train]
    pr_tab = [[eval_atom(a, rows) for a in atoms] for (_t, _s, _e, rows) in probes]
    q_tab = [[eval_atom(a, rows) for a in atoms] for (_t, _s, _e, rows) in queries]

    ntrain = len(train)
    classes = {}  # sig -> dict(count, rep, members)
    if len(sources) >= 1 and len(probes) >= 1 and atoms:
        lits = [(a, neg) for a in range(len(atoms)) for neg in (False, True)]

        def lit_val(tab_row, li):
            a, neg = li
            return (not tab_row[a]) if neg else tab_row[a]

        ok_lits = []
        for li in lits:
            good = True
            for s in sources:
                cnt = sum(1 for i in range(ntrain) if train[i][1] == s and lit_val(tr_tab[i], li))
                if cnt < S:
                    good = False
                    break
            if good:
                ok_lits.append(li)

        for width in range(1, B + 1):
            for combo in itertools.combinations(ok_lits, width):
                idxs = [c[0] for c in combo]
                if len(set(idxs)) != width:
                    continue
                # cond 3
                if not all(any(lit_val(tr_tab[i], li) for li in combo) for i in range(ntrain)):
                    continue
                # cond 4
                good = True
                for li in combo:
                    others = [x for x in combo if x is not li]
                    for s in sources:
                        cnt = sum(1 for i in range(ntrain)
                                  if train[i][1] == s and lit_val(tr_tab[i], li)
                                  and not any(lit_val(tr_tab[i], o) for o in others))
                        if cnt < W:
                            good = False
                            break
                    if not good:
                        break
                if not good:
                    continue
                # cond 5
                false_positions = [j for j in range(len(probes))
                                   if not any(lit_val(pr_tab[j], li) for li in combo)]
                if not false_positions:
                    continue
                sig = 0
                for j in range(len(probes)):
                    if any(lit_val(pr_tab[j], li) for li in combo):
                        sig |= 1 << j
                e = classes.get(sig)
                if e is None:
                    e = {"count": 0, "rep": None, "members": []}
                    classes[sig] = e
                e["count"] += 1
                e["members"].append(combo)
                if e["rep"] is None:
                    e["rep"] = combo

    nprobe = len(probes)
    width = (nprobe + 3) // 4
    out_classes = []
    for sig, e in classes.items():
        out_classes.append({
            "signature": "%0*x" % (width, sig),
            "members": e["count"],
            "representative": {"or": [{"atom": a, "negated": n} for a, n in e["rep"]]},
            "_members": [[list(m) for m in e["members"]]],
        })

    out_queries = []
    for qi in range(len(queries)):
        must = 0
        may = 0
        for sig, e in classes.items():
            vals = []
            for combo in e["members"]:
                v = any((not q_tab[qi][a]) if neg else q_tab[qi][a] for a, neg in combo)
                vals.append(v)
            if not any(vals):
                must += 1
            if not all(vals):
                may += 1
        status = "violating" if must > 0 else ("ambiguous" if may > 0 else "consistent")
        out_queries.append({"trace": queries[qi][0], "end": queries[qi][2],
                            "must": must, "may": may, "status": status})
    return {"version": 1, "classes": out_classes, "queries": out_queries}


if __name__ == "__main__":
    req = json.load(sys.stdin)
    print(json.dumps(solve(req)))
