"""Random valid-request generator for cross-checking main.py against ref.py."""
import json
import random
import sys

NUM = ("TIME", "SIZE", "COUNT")
NAMECH = "abcdefghijklmnopqrstuvwxyz0123456789_"
IDCH = "abcdefghij0123456789_.:-"


def gen_schema(rng):
    n = rng.randint(1, 5)
    names = rng.sample(["a", "b", "c", "d", "e", "f", "g", "bytes", "pkt", "src", "fl"], n)
    fields = []
    for nm in names:
        t = rng.choice(["TIME", "SIZE", "COUNT", "ID", "FLAG"])
        if t in NUM:
            lo = rng.randint(-3, 2)
            hi = lo + rng.randint(0, 6)
            fields.append({"name": nm, "type": t, "min": lo, "max": hi})
        elif t == "ID":
            k = rng.randint(1, 3)
            vals = []
            while len(vals) < k:
                v = "".join(rng.choice(IDCH) for _ in range(rng.randint(1, 4)))
                if v not in vals:
                    vals.append(v)
            fields.append({"name": nm, "type": "ID", "values": vals})
        else:
            fields.append({"name": nm, "type": "FLAG"})
    return fields


def gen_row(fields, rng):
    out = []
    for f in fields:
        if f["type"] in NUM:
            out.append(rng.randint(f["min"], f["max"]))
        elif f["type"] == "ID":
            out.append(rng.choice(f["values"]))
        else:
            out.append(rng.choice([True, False]))
    return out


def gen_trace(rng, tid, fields, nrows, sources):
    ts = rng.sample(range(-50, 200), nrows)
    rows = [{"t": t, "values": gen_row(fields, rng)} for t in ts]
    rng.shuffle(rows)
    return {"id": tid, "source": rng.choice(sources), "rows": rows}


def gen_term(rng, fields, ftype, K, quant, depth, budget):
    budget[0] -= 1
    cand_fields = [f for f in fields if f["type"] == ftype]
    choices = ["const"]
    if cand_fields:
        choices += ["field", "field"]
        if ftype in NUM and depth < 4:
            choices += ["scale", "add", "agg", "agg"]
    kind = rng.choice(choices)
    if kind == "const":
        if ftype in NUM:
            return {"const": rng.randint(-4, 8), "type": ftype}
        if ftype == "ID":
            allvals = set()
            for f in fields:
                if f["type"] == "ID":
                    allvals.update(f["values"])
            allvals.add("zz")
            return {"const": rng.choice(sorted(allvals)), "type": "ID"}
        return {"const": rng.choice([True, False]), "type": "FLAG"}
    if kind == "field":
        f = rng.choice(cand_fields)
        if quant and rng.random() < 0.5:
            at = "$"
        else:
            at = rng.randrange(K)
        return {"field": f["name"], "at": at}
    if kind == "scale":
        return {"scale": rng.randint(-4, 8),
                "term": gen_term(rng, fields, ftype, K, quant, depth + 1, budget)}
    if kind == "add":
        return {"add": [gen_term(rng, fields, ftype, K, quant, depth + 1, budget),
                        gen_term(rng, fields, ftype, K, quant, depth + 1, budget)]}
    numfields = [f for f in fields if f["type"] == ftype]
    f = rng.choice(numfields)
    a = rng.randrange(K)
    z = rng.randint(a, K - 1)
    return {"aggregate": rng.choice(["sum", "mean", "min", "max"]),
            "field": f["name"], "from": a, "to": z}


def gen_atom(rng, fields, K):
    types = [f["type"] for f in fields] + list(NUM) + ["ID", "FLAG"]
    ftype = rng.choice(types)
    quant = rng.random() < 0.3
    budget = [64]

    def cmp_node():
        left = gen_term(rng, fields, ftype, K, quant, 1, budget)
        right = gen_term(rng, fields, ftype, K, quant, 1, budget)
        ops = ["eq", "ne", "lt", "le", "gt", "ge"] if ftype in NUM else ["eq", "ne"]
        return {"cmp": rng.choice(ops), "left": left, "right": right}

    if quant:
        a = rng.randrange(K)
        z = rng.randint(a, K - 1)
        return {"quantifier": rng.choice(["any", "all"]), "from": a, "to": z,
                "predicate": cmp_node()}
    return cmp_node()


def gen_request(rng):
    K = rng.choice([1, 1, 2, 2, 3, 4, 5, 8])
    fields = gen_schema(rng)
    natoms = rng.randint(0, 6)
    atoms = [gen_atom(rng, fields, K) for _ in range(natoms)]
    sources = ["s%d" % i for i in range(rng.randint(1, 3))]
    ntrain = rng.randint(0, 4)
    train = [gen_trace(rng, "tr%d" % i, fields, rng.randint(0, 8), sources)
             for i in range(ntrain)]
    nprobe = rng.randint(0, 3)
    probes = [gen_trace(rng, "pr%d" % i, fields, rng.randint(1, 5), sources)
              for i in range(nprobe)]
    nq = rng.randint(0, 3)
    queries = [gen_trace(rng, "q%d" % i, fields, rng.randint(1, 6), sources)
               for i in range(nq)]
    return {
        "version": 1,
        "window": K,
        "schema": fields,
        "atoms": atoms,
        "policy": {"max_width": rng.randint(1, 4),
                   "min_support": rng.randint(1, 3),
                   "min_witness": rng.randint(1, 3)},
        "train": train,
        "probes": probes,
        "queries": queries,
    }


if __name__ == "__main__":
    seed = int(sys.argv[1])
    rng = random.Random(seed)
    sys.stdout.write(json.dumps(gen_request(rng)))
