import json, subprocess, sys, random
sys.path.insert(0, '/app/tmp/work')
import gen2, ref

def norm(resp):
    if 'error' in resp: return resp
    classes = {}
    for c in resp['classes']:
        sig = c['signature']
        assert sig not in classes, 'dup sig'
        rep = c['representative']['or']
        key = tuple(sorted((l['atom'], l['negated']) for l in rep))
        classes[sig] = (c['members'], key)
    return {'version': resp['version'], 'classes': classes, 'queries': resp['queries']}

n = int(sys.argv[1]); start = int(sys.argv[2]) if len(sys.argv)>2 else 0
bad = 0
stats = {'classes':0,'members':0,'nonempty':0,'queries':0,'ambiguous':0,'violating':0,'multi_member':0}
for seed in range(start, start+n):
    rng = random.Random(seed)
    req = gen2.gen(rng)
    text = json.dumps(req)
    p = subprocess.run(['/app/submission/run.sh'], input=text.encode(), capture_output=True, cwd='/app/submission')
    if p.returncode != 0:
        print('SEED',seed,'EXIT',p.returncode,p.stderr.decode()[:1500]); bad+=1; continue
    got = json.loads(p.stdout.decode())
    exp = ref.solve(json.loads(text))
    g, e = norm(got), norm(exp)
    stats['classes'] += len(e['classes']); stats['queries'] += len(e['queries'])
    stats['members'] += sum(v[0] for v in e['classes'].values())
    stats['multi_member'] += sum(1 for v in e['classes'].values() if v[0]>1)
    if e['classes']: stats['nonempty'] += 1
    for q in e['queries']:
        stats[q['status']] = stats.get(q['status'],0)+1
    if g != e:
        bad += 1
        print('SEED',seed,'MISMATCH')
        print(' got:', json.dumps(g)[:900])
        print(' exp:', json.dumps(e)[:900])
        open('/app/tmp/work/fail2_%d.json'%seed,'w').write(text)
        if bad>=3: break
print('done bad=',bad,stats)
