"""Third generator: FLAG-heavy, few probes, aimed at multi-member classes and ambiguity."""
import json, random, sys


def gen(rng):
    K = rng.choice([1, 1, 2, 2, 3])
    nf = rng.randint(2, 5)
    names = rng.sample(["a", "b", "c", "d", "e", "f", "g"], nf)
    fields = []
    for nm in names:
        if rng.random() < 0.75:
            fields.append({"name": nm, "type": "FLAG"})
        else:
            hi = rng.randint(0, 2)
            fields.append({"name": nm, "type": rng.choice(["SIZE", "COUNT", "TIME"]),
                           "min": 0, "max": hi})

    def val(f, skew):
        if f["type"] == "FLAG":
            return rng.random() < skew
        return rng.randint(f["min"], min(f["max"], f["min"] + 1))

    atoms = []
    for f in fields:
        if rng.random() < 0.9:
            if f["type"] == "FLAG":
                c = {"const": True, "type": "FLAG"}
                op = rng.choice(["eq", "eq", "ne"])
                left = {"field": f["name"], "at": rng.randrange(K)}
            else:
                c = {"const": rng.randint(f["min"], f["max"]), "type": f["type"]}
                op = rng.choice(["le", "ge", "lt", "gt", "eq", "ne"])
                left = {"field": f["name"], "at": rng.randrange(K)}
            atoms.append({"cmp": op, "left": left, "right": c})
    if atoms and rng.random() < 0.6 and len(atoms) < 20:
        atoms.append(json.loads(json.dumps(rng.choice(atoms))))
    if K > 1 and rng.random() < 0.4:
        f = rng.choice(fields)
        a = rng.randrange(K)
        z = rng.randint(a, K - 1)
        if f["type"] == "FLAG":
            pred = {"cmp": "eq", "left": {"field": f["name"], "at": "$"},
                    "right": {"const": True, "type": "FLAG"}}
        else:
            pred = {"cmp": "ge", "left": {"field": f["name"], "at": "$"},
                    "right": {"const": f["min"], "type": f["type"]}}
        atoms.append({"quantifier": rng.choice(["any", "all"]), "from": a, "to": z,
                      "predicate": pred})
    if len(atoms) > 20:
        atoms = atoms[:20]

    def mk(tid, srcs, n, skew):
        ts = rng.sample(range(0, 400), n)
        return {"id": tid, "source": rng.choice(srcs),
                "rows": [{"t": t, "values": [val(f, skew) for f in fields]} for t in ts]}

    nsrc = rng.choice([1, 1, 2, 3])
    srcs = ["s%d" % i for i in range(nsrc)]
    train = [mk("tr%d" % i, srcs, rng.randint(K, K + 5), rng.choice([0.6, 0.8, 1.0]))
             for i in range(rng.randint(1, 3))]
    probes = [mk("pr%d" % i, srcs, rng.randint(1, 3), rng.choice([0.2, 0.5]))
              for i in range(rng.randint(1, 2))]
    queries = [mk("q%d" % i, srcs, rng.randint(1, 5), rng.choice([0.3, 0.5, 0.7]))
               for i in range(rng.randint(0, 3))]
    return {"version": 1, "window": K, "schema": fields, "atoms": atoms,
            "policy": {"max_width": rng.choice([2, 3, 4]),
                       "min_support": rng.choice([1, 1, 2]),
                       "min_witness": rng.choice([1, 1, 2])},
            "train": train, "probes": probes, "queries": queries}


if __name__ == "__main__":
    rng = random.Random(int(sys.argv[1]))
    sys.stdout.write(json.dumps(gen(rng)))
