    problems = []
    if 'error' in exp:
        if got != exp: problems.append('error mismatch')
        return problems
    if got.get('version') != 1: problems.append('version')
    ec = {}
    for c in exp['classes']:
        members = set()
        for grp in c['_members']:
            for m in grp:
                members.add(cls_key([(l[0], l[1]) for l in m]))
        ec[c['signature']] = (c['members'], members)
    gc = {}
    for c in got['classes']:
        sig = c['signature']
        if sig in gc: problems.append('dup signature %s' % sig)
        rep = cls_key([(l['atom'], l['negated']) for l in c['representative']['or']])
        gc[sig] = (c['members'], rep, c['representative'])
    if set(ec) != set(gc):
        problems.append('signature sets differ: missing=%s extra=%s' % (set(ec)-set(gc), set(gc)-set(ec)))
    for sig in set(ec) & set(gc):
        em, eset = ec[sig]
        gm, grep, grepobj = gc[sig]
        if em != gm: problems.append('sig %s members %d != %d' % (sig, em, gm))
        if grep not in eset:
            problems.append('sig %s representative %r not an eligible member (members=%r)' % (sig, grep, sorted(eset)))
        # structural checks
        if set(grepobj.keys()) != {'or'}: problems.append('representative keys')
        for l in grepobj['or']:
            if set(l.keys()) != {'atom','negated'}: problems.append('literal keys')
            if type(l['negated']) is not bool: problems.append('negated not bool')
            if type(l['atom']) is not int: problems.append('atom not int')
    if got['queries'] != [{k:v for k,v in q.items()} for q in exp['queries']]:
        problems.append('queries differ')
        for a,b in zip(got['queries'], exp['queries']):
            if a != b:
                problems.append('  got %r exp %r' % (a,b))
                break
    return problems

def run(modname, n, start, extra_stats=True):
    mod = __import__(modname)
    import ref
    bad = 0
    stats = {'classes':0,'members':0,'nonempty':0,'queries':0,'ambiguous':0,'violating':0,'multi_member':0,'seeds_with_cls':0}
    for seed in range(start, start+n):
        rng = random.Random(seed)
        req = mod.gen(rng)
        text = json.dumps(req)
        p = subprocess.run(['/app/submission/run.sh'], input=text.encode(), capture_output=True, cwd='/app/submission')
        if p.returncode != 0:
            print('SEED',seed,'EXIT',p.returncode,p.stderr.decode()[:1500]); bad+=1; continue
        got = json.loads(p.stdout.decode())
        exp = ref.solve(json.loads(text))
        if extra_stats:
            stats['classes'] += len(exp['classes']); stats['queries'] += len(exp['queries'])
            stats['members'] += sum(c['members'] for c in exp['classes'])
            stats['multi_member'] += sum(1 for c in exp['classes'] if c['members']>1)
            if exp['classes']: stats['seeds_with_cls'] += 1
            for q in exp['queries']:
                stats[q['status']] = stats.get(q['status'],0)+1
        problems = check(got, exp, seed)
        if problems:
            bad += 1
            print('SEED',seed,'PROBLEMS:', problems[:6])
            open('/app/tmp/work/fail_%s_%d.json'%(modname,seed),'w').write(text)
            if bad>=4: break
    print(modname,'done bad=',bad,stats)

if __name__ == '__main__':
    run(sys.argv[1], int(sys.argv[2]), int(sys.argv[3]) if len(sys.argv)>3 else 0)
