class BitCounter(object):
    """Bit-sliced multiset counter: add bitsets, later read per-position counts."""

    __slots__ = ("bits",)

    def __init__(self):
        self.bits = []

    def add(self, value):
        bits = self.bits
        k = 0
        while value:
            if k == len(bits):
                bits.append(0)
            carry = bits[k] & value
            bits[k] ^= value
            value = carry
            k += 1

    def count_at(self, pos):
        total = 0
        weight = 1
        for b in self.bits:
            if (b >> pos) & 1:
                total += weight
            weight <<= 1
        return total


def mine(train_ctx, train_sources, train_bits, probe_bits, query_bits,
         natoms, width_limit, min_support, min_witness, ntrain, nprobe, nquery):
    classes = {}
    if natoms == 0:
        return classes
    full_tr = (1 << ntrain) - 1
    full_pr = (1 << nprobe) - 1
    full_q = (1 << nquery) - 1

    # per-source masks over training contexts; a training source without any
    # context is still a source and can never meet a positive threshold
    nsources = len(train_sources)
    if nsources == 0 or nprobe == 0:
        return classes
    src_index = {}
    for s in train_sources:
        src_index[s] = len(src_index)
    src_mask = [0] * nsources
    for idx, ctx in enumerate(train_ctx):
        src_mask[src_index[ctx[2]]] |= 1 << idx

    lit_tr = [None] * (2 * natoms)
    lit_pr = [None] * (2 * natoms)
    lit_q = [None] * (2 * natoms)
    for a in range(natoms):
        lit_tr[2 * a] = train_bits[a]
        lit_tr[2 * a + 1] = full_tr ^ train_bits[a]
        lit_pr[2 * a] = probe_bits[a]

