def mine(train_ctx, train_sources, train_bits, probe_bits, query_bits,
         natoms, width_limit, min_support, min_witness, ntrain, nprobe, nquery):
    classes = {}
    if natoms == 0:
        return classes
    full_tr = (1 << ntrain) - 1
    full_pr = (1 << nprobe) - 1
    full_q = (1 << nquery) - 1

    # per-source masks over training contexts; a training source without any
    # context is still a source and can never meet a positive threshold
    nsources = len(train_sources)
    if nsources == 0 or nprobe == 0:
        return classes
    src_index = {}
    for s in train_sources:
        src_index[s] = len(src_index)
    src_mask = [0] * nsources
    for idx, ctx in enumerate(train_ctx):
        src_mask[src_index[ctx[2]]] |= 1 << idx

    lit_tr = [None] * (2 * natoms)
    lit_pr = [None] * (2 * natoms)
    lit_q = [None] * (2 * natoms)
    for a in range(natoms):
        lit_tr[2 * a] = train_bits[a]
        lit_tr[2 * a + 1] = full_tr ^ train_bits[a]
        lit_pr[2 * a] = probe_bits[a]
        lit_pr[2 * a + 1] = full_pr ^ probe_bits[a]
        lit_q[2 * a] = query_bits[a]
        lit_q[2 * a + 1] = full_q ^ query_bits[a]

    thresh_pooled = min_witness * nsources

    def witness_ok(wset):
        if wset.bit_count() < thresh_pooled:
            return False
        for s in range(nsources):
            if (wset & src_mask[s]).bit_count() < min_witness:
                return False
        return True

    def supported(li):
        bits = lit_tr[li]
        for s in range(nsources):
            if (bits & src_mask[s]).bit_count() < min_support:
                return False
        return True

    supp_negs = []
    for a in range(natoms):
        choices = []
        if supported(2 * a):
            choices.append(False)
        if supported(2 * a + 1):
            choices.append(True)
        supp_negs.append(choices)

    # suffix union of training coverage of all supported literals from atom i on
    suffix = [0] * (natoms + 1)
    acc = 0
    for a in range(natoms - 1, -1, -1):
        for neg in supp_negs[a]:
            acc |= lit_tr[2 * a + (1 if neg else 0)]
        suffix[a] = acc

    clause = []  # list of (literal index, train bits)

    def leaf(orset_tr, orset_pr, orset_q):
        if orset_tr != full_tr:
            return
        if orset_pr == full_pr:
            return
        n = len(clause)
        for i in range(n):
            li, bits = clause[i]
            others = 0
            for j in range(n):
                if j != i:
                    others |= clause[j][1]
            if not witness_ok(bits & ~others):
                return
        entry = classes.get(orset_pr)
        if entry is None:
            # entry layout: [count, representative, or-set, and-set]
            classes[orset_pr] = [1, tuple(li for li, _ in clause), orset_q,
                                 full_q & orset_q]
        else:
            entry[0] += 1
            entry[2] |= orset_q
            entry[3] &= orset_q

    def dfs(start, orset_tr, orset_pr, orset_q):
        if clause:
            leaf(orset_tr, orset_pr, orset_q)
        if len(clause) >= width_limit:
            return
        for a in range(start, natoms):
            choices = supp_negs[a]
            if not choices:
                continue
            if (orset_tr | suffix[a]) != full_tr:
                break
            for neg in choices:
                li = 2 * a + (1 if neg else 0)
                bits = lit_tr[li]
                fresh = bits & ~orset_tr
                if fresh == 0:
                    continue
                if not witness_ok(fresh):
                    continue
                clause.append((li, bits))
                dfs(a + 1, orset_tr | bits, orset_pr | lit_pr[li],
                    orset_q | lit_q[li])
                clause.pop()

    dfs(0, 0, 0, 0)
    return classes


def format_signature(sig, nprobe):
    width = (nprobe + 3) // 4
    return "%0*x" % (width, sig)


