class CodeBuilder(object):
    def __init__(self, fidx):
        self.fidx = fidx
        self.stmts = []
        self.memo = {}
        self.count = 0

    def hoist(self, code):
        var = self.memo.get(code)
        if var is None:
            var = "v%d" % self.count
            self.count += 1
            self.memo[code] = var
            self.stmts.append("%s=%s" % (var, code))
        return var

    def term(self, node, binding):
        keys = set(node.keys())
        if keys == {"field", "at"}:
            at = node["at"]
            if at == "$":
                if binding is None:
                    die("E_SCHEMA")
                off = binding
            else:
                off = at
            return "r[%d][%d]" % (off, self.fidx[node["field"]])
        if keys == {"const", "type"}:
            val = node["const"]
            if type(val) is bool:
                return "True" if val else "False"
            if type(val) is int:
                return "(%d)" % val
            return repr(val)
        if keys == {"scale", "term"}:
            code = "(%d*%s)" % (node["scale"], self.term(node["term"], binding))
            return code if has_dollar(node) else self.hoist(code)
        if keys == {"add"}:
            parts = node["add"]
            code = "(%s+%s)" % (self.term(parts[0], binding),
                                self.term(parts[1], binding))
            return code if has_dollar(node) else self.hoist(code)
        op = node["aggregate"]
        fi = self.fidx[node["field"]]
        terms = ["r[%d][%d]" % (d, fi) for d in range(node["from"], node["to"] + 1)]
        if op == "sum":
            code = "(" + "+".join(terms) + ")"
        elif op == "mean":
            code = "_F((%s),%d)" % ("+".join(terms), len(terms))
        elif len(terms) == 1:
            code = terms[0]
        elif op == "min":
            code = "min(%s)" % (",".join(terms),)
        else:
            code = "max(%s)" % (",".join(terms),)
        return self.hoist(code)

    def cmp(self, node, binding):
        return "(%s%s%s)" % (self.term(node["left"], binding),
                             CMP_OPS[node["cmp"]],
                             self.term(node["right"], binding))

    def build(self, atom):
        if "quantifier" in atom:
            pred = atom["predicate"]
            bodies = []
            seen = set()
            for j in range(atom["from"], atom["to"] + 1):
                code = self.cmp(pred, j)
                if code not in seen:
                    seen.add(code)
                    bodies.append(code)
            if len(bodies) == 1:
                expr = bodies[0]
            else:
                joiner = " or " if atom["quantifier"] == "any" else " and "
                expr = "(" + joiner.join(bodies) + ")"
        else:
            expr = self.cmp(atom, None)
        lines = ["def _atom(r, _F=_F, min=min, max=max):"]
        for stmt in self.stmts:
            lines.append("    " + stmt)
        lines.append("    return " + expr)
        source = "\n".join(lines) + "\n"
        namespace = {"_F": Fraction, "min": min, "max": max}
        exec(compile(source, "<atom>", "exec"), namespace)  # noqa: S102
        return namespace["_atom"]


def compile_atoms(atoms, fidx):
    return [CodeBuilder(fidx).build(atom) for atom in atoms]


def eval_partition(contexts, fns):
    natoms = len(fns)
    if natoms == 0 or not contexts:
        return [0] * natoms
    rowsets = [ctx[0] for ctx in contexts]
    bits = []
    for fn in fns:
        values = list(map(fn, rowsets))
        acc = 0
        bit = 1
        for v in values:
            if v:
                acc |= bit
            bit <<= 1
        bits.append(acc)
    return bits


